window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[194]={"id":"194","numero":194,"titre":"Lupus systémique & SAPL","objectifs":[{"id":"194-1","rang":"A","rubrique":"Définition","titre":"Savoir que le lupus systémique (LS) est une maladie auto-immune polymorphe","contenu":"<p>Le <span class=\"kw-def\">lupus systémique</span> (LS), ou <span class=\"kw-def\">lupus érythémateux systémique</span> (<span class=\"kw-clinique\">LES</span>), est une <strong><span class=\"kw-def\">maladie auto-immune systémique</span></strong>, non spécifique d'organe. Sur le plan <span class=\"kw-ttt\">biologique</span>, il se caractérise par la présence d'<span class=\"kw-bio\">auto-anticorps</span> dirigés contre des <span class=\"kw-bio\">antigènes d'origine nucléaire</span>.</p>\n      <p>Son expression clinique est <strong>très polymorphe</strong> : <span class=\"kw-clinique\">les</span> premières manifestations peuvent intéresser <span class=\"kw-clinique\">n'importe quel organe</span>, et les rechutes ne touchent pas forcément le même. On oppose schématiquement deux profils de tableaux :</p>\n      <ul>\n        <li><strong>Formes bénignes et fréquentes</strong> — atteintes <span class=\"kw-clinique\">cutanéo-articulaires</span> (<span class=\"kw-clinique\">rash</span> malaire, <span class=\"kw-clinique\">arthralgies</span>) ; <span class=\"kw-def\">pronostic</span> favorable.</li>\n        <li><strong>Formes plus rares et sévères</strong> — atteintes <span class=\"kw-alerte\">viscérales</span> (rénale, neurologique, hématologique) qui peuvent <span class=\"kw-alerte\">mettre en jeu le pronostic vital</span>.</li>\n      </ul>\n      <p>La maladie résulte d'une <span class=\"kw-def\">perte de tolérance aux antigènes du soi</span>, mettant en jeu : toxicité directe des auto-AC, <span class=\"kw-bio\">complexes immuns circulants</span>, défaut de <span class=\"kw-bio\">clairance</span> des corps apoptotiques, <span class=\"kw-clinique\">lymphocytes T et B autoréactifs</span>, activation des cellules dendritiques plasmacytoïdes (production d'<span class=\"kw-bio\">interféron alpha</span>) et activation du <span class=\"kw-bio\">complément</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-def\">Lupus</span> systémique = maladie <span class=\"kw-etio\">auto-immune</span> <em>polymorphe</em> — c'est ce caractère protéiforme qui en fait la difficulté diagnostique.</div>","frequence":2},{"id":"194-2","rang":"A","rubrique":"Définition","titre":"Savoir que le syndrome des anti-phospholipides (SAPL) peut être primaire ou secondaire","contenu":"<p>Le <span class=\"kw-def\">syndrome des anti-phospholipides</span> (SAPL) associe des <span class=\"kw-clinique\">manifestations thrombotiques ou obstétricales</span> à la présence persistante d'<span class=\"kw-bio\">anticorps anti-phospholipides</span>. On en distingue deux formes selon le contexte :</p>\n      <ul>\n        <li><strong>SAPL primaire</strong> (<span class=\"kw-chiffre\">≈ 50 %</span>) — survient <span class=\"kw-def\">en dehors de tout cadre pathologique défini</span>, de façon isolée.</li>\n        <li><strong>SAPL secondaire</strong> (<span class=\"kw-chiffre\">≈ 50 %</span>) — associé à une autre <span class=\"kw-def\">maladie auto-immune</span>, essentiellement le <span class=\"kw-def\">lupus systémique</span> : un SAPL est observé chez <span class=\"kw-chiffre\">20-30 %</span> des patients lupiques.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Terrain</span></strong> — le SAPL affecte surtout la <span class=\"kw-clinique\">femme jeune</span>, mais peut survenir à <span class=\"kw-clinique\">tout âge</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant un <span class=\"kw-def\">lupus</span> systémique, toujours rechercher un SAPL associé : il conditionne le risque <span class=\"kw-etio\">thrombotique</span> et la prise en charge anticoagulante.</div>","frequence":1},{"id":"194-3","rang":"B","rubrique":"Prévalence","titre":"Connaître la population la plus fréquemment concernée par le LS","contenu":"<p>Le <span class=\"kw-def\">lupus systémique</span> est une <strong>maladie rare</strong> : sa <span class=\"kw-def\">prévalence</span> en France est d'environ <span class=\"kw-chiffre\">40/100 000</span> (sous le seuil de <span class=\"kw-chiffre\">1/2000</span> définissant <span class=\"kw-clinique\">les</span> maladies rares). Il reste néanmoins la <strong>maladie systémique la plus fréquente</strong> après le <span class=\"kw-clinique\">syndrome de Gougerot</span>-<span class=\"kw-clinique\">Sjögren</span>.</p>\n      <p><strong>Population la plus concernée</strong> :</p>\n      <ul>\n        <li><strong>Sexe</strong> — nette <span class=\"kw-clinique\">prédominance féminine</span>, sex-ratio <span class=\"kw-chiffre\">9 femmes / 1 homme</span>.</li>\n        <li><strong>Âge</strong> — survenue pendant la <span class=\"kw-clinique\">période d'activité ovarienne</span>, fréquence maximale entre <span class=\"kw-chiffre\">10 et 40 ans</span>.</li>\n        <li><strong>Ethnie</strong> — <span class=\"kw-def\">lupus</span> plus fréquent et plus <span class=\"kw-alerte\">sévère</span> chez <span class=\"kw-clinique\">les</span> personnes à peau noire (populations noires et asiatiques des USA et des Caraïbes) ; <span class=\"kw-def\">prévalence</span> faible chez les populations noires vivant en Afrique.</li>\n      </ul>\n      <p><strong>Facteurs étiologiques</strong> — <span class=\"kw-def\">physiopathologie</span> mal connue, résultant d'une combinaison de facteurs :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Génétiques</span> — <span class=\"kw-def\">lupus</span> génétiques de l'enfant par déficit en <span class=\"kw-bio\">C1q</span>, <span class=\"kw-bio\">C2</span> et <span class=\"kw-bio\">C4</span>.</li>\n        <li><span class=\"kw-etio\">Environnementaux</span> — soleil (<span class=\"kw-etio\">UVB</span> > <span class=\"kw-ttt\">UVA</span>), <span class=\"kw-etio\">œstrogènes</span>, infection à <span class=\"kw-etio\">EBV</span> chez l'enfant, <span class=\"kw-etio\">tabac</span>, stress.</li>\n        <li><span class=\"kw-etio\">Médicaments inducteurs</span> — responsables du <span class=\"kw-def\">lupus</span> <span class=\"kw-etio\">médicamenteux</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Repère épidémiologique.</strong> Le <span class=\"kw-def\">lupus</span> systémique est la maladie systémique la plus fréquente après le <span class=\"kw-clinique\">syndrome de Gougerot</span>-<span class=\"kw-clinique\">Sjögren</span>.</div>","frequence":0},{"id":"194-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de repérage des principales atteintes viscérales du LS","contenu":"<p>Le <span class=\"kw-def\">lupus systémique</span> est une maladie <strong>polymorphe</strong> : ses manifestations peuvent toucher tous <span class=\"kw-clinique\">les</span> organes. Connaître leur fréquence et leur mode de repérage est essentiel pour dépister les atteintes viscérales.</p>\n      <p><strong>Manifestations cliniques par ordre de fréquence</strong> :</p>\n      <table >\n        <thead><tr><th>Fréquence</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquent</strong> (&gt;<span class=\"kw-chiffre\"> 50 %</span>)</td><td><span class=\"kw-clinique\">Rash</span> malaire (<span class=\"kw-def\">lupus</span> aigu), <span class=\"kw-clinique\">arthralgies / arthrites</span>, <span class=\"kw-clinique\">fièvre</span></td></tr>\n          <tr><td><strong>Moins fréquent</strong> (<span class=\"kw-chiffre\">30-50 %</span>)</td><td><span class=\"kw-clinique\">Photosensibilité</span>, syndrome sec, <span class=\"kw-clinique\">sérites</span> (pleurésie, péricardite), atteinte rénale, <span class=\"kw-clinique\">phénomène de Raynaud</span>, atteintes neurologiques</td></tr>\n          <tr><td><strong>Peu fréquent</strong> (<span class=\"kw-chiffre\">10-30 %</span>)</td><td>Ulcérations buccales, <span class=\"kw-def\">lupus</span> discoïde, <span class=\"kw-def\">lupus</span> subaigu, <span class=\"kw-clinique\">splénomégalie</span>, adénomégalies</td></tr>\n          <tr><td><strong>Rare</strong> (&lt;<span class=\"kw-chiffre\"> 10 %</span>)</td><td>Atteinte pulmonaire hors sérite, myosite</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Repérage des principales atteintes viscérales</strong> :</p>\n      <table >\n        <thead><tr><th>Organe</th><th>Fréquence</th><th>Modalités de repérage</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Rénale</span></td><td><span class=\"kw-chiffre\">40 %</span></td><td><span class=\"kw-bio\">Bandelette urinaire</span> (<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-clinique\">hématurie</span>), <span class=\"kw-bio\">créatininémie</span>, RPC sur échantillon, <span class=\"kw-bio\">ECBU</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Cardiaque</span></td><td><span class=\"kw-chiffre\">10-30 %</span></td><td><span class=\"kw-imagerie\">ECG et ETT</span> systématiques ; péricardite (la plus fréquente) très corticosensible</td></tr>\n          <tr><td><span class=\"kw-clinique\">Pulmonaire</span></td><td><span class=\"kw-chiffre\">15-40 %</span></td><td><span class=\"kw-imagerie\">Radiographie thoracique</span> ; pleurésie exsudative corticosensible</td></tr>\n          <tr><td><span class=\"kw-clinique\">Neuro-psychiatrique</span></td><td><span class=\"kw-chiffre\">20-50 %</span></td><td><span class=\"kw-imagerie\">IRM cérébrale</span> devant toute suspicion d'atteinte centrale</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hématologique</span></td><td>—</td><td><span class=\"kw-bio\">NFS</span> (cytopénies) ; recherche d'<span class=\"kw-clinique\">adénopathies</span> et de <span class=\"kw-clinique\">splénomégalie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Péricardite et pleurésie lupiques sont très corticosensibles. En revanche, le <span class=\"kw-def\">lupus</span> <strong>ne donne pas de pneumopathie interstitielle diffuse (PID)</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 213 — Anémie · 214 — Thrombopénie · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":2},{"id":"194-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales lésions cutanées spécifiques","contenu":"<p><span class=\"kw-clinique\">Les</span> manifestations cutanées concernent <span class=\"kw-chiffre\">≈ 80 %</span> des patients lupiques et sont souvent <span class=\"kw-clinique\">inaugurales</span>. On distingue les <strong>lésions spécifiques</strong> (lupiques) des lésions non spécifiques.</p>\n      <table >\n        <thead><tr><th>Forme</th><th><span class=\"kw-clinique\">Lésion</span> élémentaire</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Lupus aigu</span></td><td><span class=\"kw-clinique\">Vespertilio</span> — <span class=\"kw-clinique\">rash</span> malaire en aile de papillon</td><td><strong>Photosensible :</strong> distribution photo-exposée ; <br><strong><span class=\"kw-clinique\">Évolution</span> :</strong> non atrophiant, guérit sans cicatrice ; suit <span class=\"kw-clinique\">les</span> poussées</td></tr>\n          <tr><td><span class=\"kw-def\">Lupus subaigu</span></td><td>Lésions <span class=\"kw-clinique\">annulaires polycycliques</span> ou psoriasiformes</td><td><strong>Immunologie :</strong> associé aux <span class=\"kw-bio\">anti-SSA/Ro</span> ; <br><strong>Risque :</strong> <span class=\"kw-alerte\">lupus néonatal</span> en cas de <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><span class=\"kw-def\">Lupus chronique</span> (discoïde)</td><td>Plaques <span class=\"kw-clinique\">érythémato-squameuses</span> avec atrophie centrale et bouchons cornés folliculaires</td><td><strong><span class=\"kw-alerte\">Cicatriciel</span></strong> — alopécie définitive en zone pileuse</td></tr>\n          <tr><td>Lésions <strong>non spécifiques</strong></td><td><span class=\"kw-clinique\">Photosensibilité</span>, alopécie diffuse, ulcérations buccales / nasopharyngées, <span class=\"kw-clinique\">livedo</span>, <span class=\"kw-def\">purpura</span> vasculaire</td><td>Non lupiques en <span class=\"kw-bio\">histologie</span> ; simple valeur d'orientation</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-clinique\">photosensibilité</span> a été supprimée des critères <span class=\"kw-alerte\">ACR</span> 2019 car elle faisait double emploi avec le <span class=\"kw-clinique\">rash</span> malaire.</div>","frequence":4},{"id":"194-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de fréquence et de présentation clinique d’une atteinte rénale au cours du lupus systémique : œdèmes, bandelettes urinaires positives","contenu":"<p>L'<strong><span class=\"kw-clinique\">atteinte rénale</span></strong> (néphropathie lupique) concerne environ <span class=\"kw-chiffre\">40 %</span> des patients. C'est un <span class=\"kw-alerte\">facteur pronostique majeur</span> : son repérage précoce conditionne le <span class=\"kw-def\">pronostic</span> rénal et vital.</p>\n      <p><strong>Présentation clinique</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Œdèmes</span> — traduisant un <span class=\"kw-def\">syndrome néphrotique</span>, le plus souvent <span class=\"kw-def\">impur</span> (associé à <span class=\"kw-clinique\">HTA</span> et/ou <span class=\"kw-clinique\">hématurie</span>).</li>\n        <li><span class=\"kw-clinique\">HTA</span> — fréquente, surtout en cas de glomérulopathie grave.</li>\n        <li>Le plus souvent <span class=\"kw-alerte\">asymptomatique au début</span> — d'où l'intérêt majeur du <span class=\"kw-def\">dépistage</span> systématique.</li>\n      </ul>\n      <p><strong>Repérage — la <span class=\"kw-bio\">bandelette urinaire</span> est la pierre angulaire</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Bandelette urinaire</span> — recherche une <span class=\"kw-bio\">protéinurie</span> et une <span class=\"kw-bio\">hématurie microscopique</span> ; réalisée <span class=\"kw-chiffre\">tous les 6 mois</span> en autosurveillance.</li>\n        <li>Si la bandelette est positive : quantification par <span class=\"kw-bio\">RPC sur échantillon</span>, dosage de la <span class=\"kw-bio\">créatininémie</span> et <span class=\"kw-bio\">ECBU</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Une <span class=\"kw-bio\">bandelette urinaire</span> positive (<span class=\"kw-bio\">protéinurie</span> + <span class=\"kw-clinique\">hématurie</span>) chez un patient lupique impose la quantification de la <span class=\"kw-bio\">protéinurie</span> et doit faire discuter une <span class=\"kw-bio\">biopsie</span> rénale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":4},{"id":"194-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de SAPL","contenu":"<p>Le diagnostic de <span class=\"kw-def\">SAPL</span> repose sur l'association d'<strong>au moins 1 <span class=\"kw-def\">critère clinique</span></strong> et d'<strong>au moins 1 critère <span class=\"kw-ttt\">biologique</span> persistant</strong>. <span class=\"kw-clinique\">Les</span> critères internationaux 2023 sont des <span class=\"kw-def\">critères de classification</span>, non diagnostiques.</p>\n      <p><strong><span class=\"kw-def\">Critères cliniques</span></strong> :</p>\n      <ul>\n        <li><strong>Thromboses</strong> — veineuse, artérielle ou de la microcirculation, confirmée par <span class=\"kw-imagerie\">imagerie</span> ou <span class=\"kw-imagerie\">histologie</span> (<span class=\"kw-etio\">thrombus</span> sans inflammation vasculaire). Évoquer un SAPL devant un <span class=\"kw-alerte\">AVC ou un IDM du sujet jeune</span>, ou une thrombose de <span class=\"kw-alerte\">siège atypique</span> (veines splanchniques, membre supérieur). <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">thromboses superficielles ne sont pas un critère</span>.</li>\n        <li><strong>Manifestations obstétricales</strong> — <span class=\"kw-chiffre\">≥ 3</span> fausses couches précoces (<span class=\"kw-chiffre\">&lt; 10 SA</span>) ; <span class=\"kw-chiffre\">≥ 1</span> mort fœtale in utero (<span class=\"kw-chiffre\">≥ 10 SA</span>) avec morphologie fœtale normale ; ≥ 1 prématurité (<span class=\"kw-chiffre\">&lt; 34 SA</span>) liée à une éclampsie / prééclampsie ou une insuffisance placentaire.</li>\n      </ul>\n      <p><strong>Critères biologiques</strong> — présence persistante (<span class=\"kw-chiffre\">≥ 2 reprises espacées de ≥ 12 semaines</span>) d'au moins un anticorps :</p>\n      <table >\n        <thead><tr><th>Anticorps</th><th>Méthode de détection</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Anti-cardiolipine</span> (aCL) <span class=\"kw-chiffre\">IgG</span> / IgM</td><td><span class=\"kw-bio\">ELISA</span>, à titre élevé</td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-β2-glycoprotéine-1</span> (anti-β<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span>G</span>P1) <span class=\"kw-chiffre\">IgG</span> / IgM</td><td><span class=\"kw-bio\">ELISA</span>, à titre élevé</td></tr>\n          <tr><td><span class=\"kw-bio\">Anticoagulant circulant</span> de type lupique (ACC)</td><td><strong>Tests d'hémostase :</strong> allongement isolé du <span class=\"kw-bio\">TCA</span> ; <br><strong>Non corrigé</strong> par le mélange avec un plasma témoin ; <br><strong>Corrigé</strong> par un excès de phospholipides</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Le <span class=\"kw-alerte\">CAPS</span> (syndrome catastrophique des anti-phospholipides) = <span class=\"kw-alerte\">défaillance</span> multiviscérale en &lt;<span class=\"kw-chiffre\"> 1 semaine</span>, <span class=\"kw-def\">mortalité</span><span class=\"kw-chiffre\"> 30-50 %</span>, atteinte rénale dans <span class=\"kw-chiffre\">90 %</span> des cas. PEC = <span class=\"kw-ttt\">anticoagulation</span> + <span class=\"kw-ttt\">corticoïdes</span> fortes doses + IgIV + plasmaphérèses.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":5},{"id":"194-8","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un vespertilio","contenu":"<p>Le <span class=\"kw-def\">vespertilio</span> (<span class=\"kw-clinique\">rash</span> malaire) est la <span class=\"kw-clinique\">lésion</span> cutanée caractéristique du <span class=\"kw-def\">lupus aigu</span>. Description sémiologique :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Érythème en aile de papillon</span> — <span class=\"kw-clinique\">placard</span> érythémateux bilatéral et symétrique des <span class=\"kw-clinique\">pommettes</span> et du <span class=\"kw-clinique\">dos du nez</span>.</li>\n        <li>Distribution <strong>photo-exposée</strong> — épargne typiquement <span class=\"kw-clinique\">les</span> sillons nasogéniens.</li>\n        <li><span class=\"kw-clinique\">Photosensible</span> — déclenché ou aggravé par l'<span class=\"kw-etio\">exposition solaire</span>.</li>\n        <li><span class=\"kw-clinique\">Lésion</span> <strong>non atrophiante</strong> — guérit <span class=\"kw-clinique\">sans cicatrice</span> ni séquelle (contrairement au <span class=\"kw-def\">lupus</span> discoïde).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À compléter — image à fournir par Kevin.</strong> Cet objectif « Contenu multimédia » attend une photographie clinique de vespertilio. Aucune image n'est intégrée tant que Kevin ne l'a pas fournie (pas d'hallucination iconographique).</div>","frequence":1},{"id":"194-9","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un livedo racemosa","contenu":"<p>Le <span class=\"kw-def\">livedo racemosa</span> est un marqueur cutané majeur du <span class=\"kw-def\">SAPL</span>. Description sémiologique :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Coloration érythémateuse foncée ou bleue-violacée</span> de la peau.</li>\n        <li>Disposition en <strong><span class=\"kw-clinique\">grandes mailles ouvertes</span></strong>, en forme de mailles de filet, irrégulières et incomplètes.</li>\n        <li>Prédomine sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">fesses</span> et le <span class=\"kw-clinique\">tronc</span>.</li>\n      </ul>\n      <p><strong>À distinguer du <span class=\"kw-def\">livedo reticularis</span></strong> — celui-ci est <span class=\"kw-clinique\">hémodynamique</span>, fait de <strong><span class=\"kw-clinique\">petites mailles fermées</span></strong> et régulières, physiologique au froid, sans valeur pathologique.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter — image à fournir par Kevin.</strong> Cet objectif « Contenu multimédia » attend une photographie clinique de <span class=\"kw-clinique\">livedo</span> racemosa. Aucune image n'est intégrée tant que Kevin ne l'a pas fournie (pas d'hallucination iconographique).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":2},{"id":"194-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et l’interprétation du test de dépistage des anticorps anti-nucléaires (AAN)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">anticorps anti-nucléaires</span> (<span class=\"kw-bio\">AAN</span>, ou facteurs antinucléaires <span class=\"kw-bio\">FAN</span>) sont le <strong>test de <span class=\"kw-def\">dépistage</span></strong> de <span class=\"kw-chiffre\">première intention</span> du <span class=\"kw-def\">lupus</span>.</p>\n      <p><strong>Intérêt et interprétation</strong> :</p>\n      <ul>\n        <li><strong>Sensibilité <span class=\"kw-chiffre\">≈ 100 %</span></strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">AAN</span> sont <span class=\"kw-bio\">constants</span> dans le <span class=\"kw-def\">lupus</span> systémique. Un titre <span class=\"kw-chiffre\">&lt; 1/80</span> rend le diagnostic très improbable : c'est le <span class=\"kw-def\">critère d'entrée</span> de la <span class=\"kw-def\">classification</span> <span class=\"kw-alerte\">ACR</span>/EULAR 2019.</li>\n        <li><strong>Spécificité faible (<span class=\"kw-chiffre\">≈ 50 %</span>)</strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">AAN</span> sont peu spécifiques (positifs aussi dans d'autres MAI, infections, cancers, ou chez les sujets âgés sains).</li>\n      </ul>\n      <p><strong>Technique</strong> — détection par <span class=\"kw-bio\">immunofluorescence indirecte</span> (IFI) sur cellules <span class=\"kw-bio\">HEp-2</span>. L'interprétation associe le <strong>titre</strong> (seuil de positivité <span class=\"kw-chiffre\">&gt; 1/80</span>) et l'<strong>aspect de la fluorescence</strong>, qui oriente <span class=\"kw-clinique\">les</span> tests complémentaires :</p>\n      <ul>\n        <li><strong>Homogène</strong> — <span class=\"kw-bio\">anti-ADN</span> natif, anti-Histone.</li>\n        <li><strong>Moucheté à gros grains</strong> — <span class=\"kw-bio\">anti-Sm</span>, anti-RNP.</li>\n        <li><strong>Moucheté fin</strong> — <span class=\"kw-bio\">anti-SSA</span>/Ro, anti-SSB/La.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> tests complémentaires (<span class=\"kw-bio\">anti-ADN</span> natif, anti-ENA) ne sont réalisés que si le titre des <span class=\"kw-bio\">AAN</span> est positif — et sont orientés par l'aspect de la fluorescence.</div>","frequence":2},{"id":"194-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux auto-anticorps (hors AAN) et anomalies biologiques au cours du LS","contenu":"<p><strong>Objectif très fréquemment tombé en QCM.</strong> Au-delà des <span class=\"kw-bio\">AAN</span>, certains <span class=\"kw-bio\">auto-anticorps</span> ont une grande valeur diagnostique ou de <span class=\"kw-def\">suivi</span>.</p>\n      <table >\n        <thead><tr><th>Auto-anticorps</th><th>Sensibilité</th><th>Spécificité</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Anti-ADN natif</span> (double brin)</td><td><span class=\"kw-chiffre\">60-90 %</span></td><td><span class=\"kw-chiffre\">95-99 %</span></td><td>Corrélé à l'<span class=\"kw-clinique\">activité de la maladie</span> ; <span class=\"kw-alerte\">néphropathie ++</span> ; un taux <span class=\"kw-chiffre\">≥ 200 UI/mL</span> peut prédire une <span class=\"kw-clinique\">poussée</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-Sm</span></td><td><span class=\"kw-chiffre\">10-30 %</span></td><td><span class=\"kw-chiffre\">100 %</span></td><td>Très spécifique du LS ; reste positif même en <span class=\"kw-clinique\">rémission</span> ; plus fréquent chez <span class=\"kw-clinique\">les</span> sujets <span class=\"kw-clinique\">afro-américains et asiatiques</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-RNP</span></td><td><span class=\"kw-chiffre\">20-30 %</span></td><td><span class=\"kw-chiffre\">30 %</span></td><td>Plutôt évocateur de <span class=\"kw-def\">connectivite mixte</span> (Sharp) ; associé à myosite, <span class=\"kw-def\">syndrome de Raynaud</span>, HTAP</td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-SSA/Ro</span> et <span class=\"kw-bio\">anti-SSB/La</span></td><td><span class=\"kw-chiffre\">30-70 %</span></td><td><span class=\"kw-chiffre\">5-10 %</span></td><td><span class=\"kw-def\">Lupus</span> cutané <span class=\"kw-clinique\">subaigu</span> ; risque de <span class=\"kw-alerte\">lupus néonatal</span> (<span class=\"kw-ci\">grossesse</span> à surveiller) ; non spécifiques (<span class=\"kw-clinique\">Gougerot-Sjögren</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Anti-Histones</span></td><td>—</td><td>—</td><td>Évocateurs de <span class=\"kw-def\">lupus médicamenteux</span> (mais présents dans &gt;<span class=\"kw-chiffre\"> 50 %</span> des LS idiopathiques)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Anomalies biologiques non spécifiques</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span> — <span class=\"kw-clinique\">anémie hémolytique auto-immune</span> (test de Coombs positif), <span class=\"kw-clinique\">thrombopénie</span> périphérique (test de Dixon positif), <span class=\"kw-clinique\">lymphopénie</span>, neutropénie.</li>\n        <li><span class=\"kw-bio\">VS</span> élevée — <span class=\"kw-def\">syndrome inflammatoire</span> quasi constant lors des poussées.</li>\n        <li><span class=\"kw-bio\">Hypocomplémentémie de consommation</span> — baisse du <span class=\"kw-bio\">C3</span>, <span class=\"kw-bio\">C4</span> et <span class=\"kw-bio\">CH50</span>, traduisant l'activité de la maladie.</li>\n        <li><span class=\"kw-bio\">Hypergammaglobulinémie polyclonale</span> à l'<span class=\"kw-bio\">électrophorèse des protéines sériques</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-bio\">CRP</span> normale dans le <span class=\"kw-def\">lupus</span> actif — une <span class=\"kw-bio\">CRP</span> élevée doit faire chercher une sérite, une thrombose ou une infection. Discriminant clé en clinique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 214 — Thrombopénie</em></p>","frequence":7},{"id":"194-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes des méthodes et la place de l’anatomie pathologique pour le diagnostic des lésion cutanées","contenu":"<p>L'<span class=\"kw-def\">anatomie pathologique</span> a une place <strong>limitée</strong> dans le diagnostic du <span class=\"kw-def\">lupus</span>, qui repose avant tout sur la clinique et l'immunologie. Elle reste utile en cas de doute diagnostique ou de présentation atypique.</p>\n      <p><strong><span class=\"kw-bio\">Biopsie</span> cutanée — principes</strong> :</p>\n      <ul>\n        <li>Prélèvement réalisé sur une <span class=\"kw-clinique\">lésion cutanée typique</span> (idéalement comparée à une zone de peau saine).</li>\n        <li>Analyse en <strong><span class=\"kw-bio\">histologie</span> standard</strong> et surtout en <span class=\"kw-bio\">immunofluorescence directe</span> (IFD).</li>\n        <li>L'IFD recherche la <strong><span class=\"kw-def\">bande lupique</span></strong> — dépôts d'<span class=\"kw-bio\">IgG, IgM et C3</span> à la <span class=\"kw-def\">jonction dermo-épidermique</span>, de disposition linéaire ou granuleuse.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-bio\">biopsie</span> cutanée n'est pas systématique : elle aide surtout au diagnostic d'un <span class=\"kw-def\">lupus</span> discoïde ou d'une présentation cutanée atypique.</div>","frequence":1},{"id":"194-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de la biopsie rénale et les principales lésions rénales","contenu":"<p><strong>Objectif très fréquemment tombé en QCM.</strong> La <span class=\"kw-def\">biopsie rénale</span> (PBR) est l'examen clé devant une suspicion d'atteinte rénale lupique : elle classe la <span class=\"kw-clinique\">lésion</span> et oriente le traitement.</p>\n      <p><strong>Indications de la PBR</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Protéinurie</span> &gt; <span class=\"kw-chiffre\">0,5 g/24 h</span> (ou RPC &gt; <span class=\"kw-chiffre\">0,5 g/g</span>).</li>\n        <li><span class=\"kw-bio\">Hématurie microscopique</span> persistante.</li>\n        <li><span class=\"kw-alerte\">Insuffisance rénale aiguë</span> inexpliquée.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Classification</span> ISN/RPS — 6 classes histologiques</strong> :</p>\n      <table >\n        <thead><tr><th>Classe</th><th><span class=\"kw-clinique\">Lésion</span></th><th>Implication thérapeutique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>I</strong></td><td>Mésangiale minime</td><td>Pas de traitement spécifique</td></tr>\n          <tr><td><strong>II</strong></td><td>Mésangioproliférative</td><td><span class=\"kw-def\">Surveillance</span>, traitement léger</td></tr>\n          <tr><td><strong>III</strong></td><td>Proliférative <span class=\"kw-clinique\">focale</span> (&lt;<span class=\"kw-chiffre\"> 50 %</span> des glomérules)</td><td><span class=\"kw-alerte\">Immunosuppresseur agressif</span></td></tr>\n          <tr><td><strong>IV</strong></td><td>Proliférative <span class=\"kw-clinique\">diffuse</span> (<span class=\"kw-chiffre\">≥ 50 %</span>) — <span class=\"kw-alerte\">la plus sévère</span></td><td><span class=\"kw-alerte\">Immunosuppresseur agressif</span></td></tr>\n          <tr><td><strong>V</strong></td><td>Extra-membraneuse</td><td><span class=\"kw-def\">Syndrome néphrotique</span></td></tr>\n          <tr><td><strong>VI</strong></td><td><span class=\"kw-ttt\">Sclérose</span> avancée (&gt;<span class=\"kw-chiffre\"> 90 %</span> des glomérules)</td><td><span class=\"kw-alerte\">Dialyse à anticiper</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Classes III et IV (prolifératives) = traitement <span class=\"kw-ttt\">immunosuppresseur</span> agressif. <span class=\"kw-chiffre\">Classe V</span> (extra-membraneuse) = <span class=\"kw-def\">syndrome néphrotique</span> pur. <span class=\"kw-chiffre\">Classe VI</span> = <span class=\"kw-ttt\">sclérose</span> &gt;<span class=\"kw-chiffre\"> 90 %</span>, dialyse à anticiper.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":6},{"id":"194-14","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le mode d’évolution du LS et les atteintes viscérales pronostiques","contenu":"<p>Le <span class=\"kw-def\">lupus systémique</span> est une maladie chronique qui évolue par <strong>poussées</strong> entrecoupées de <strong>rémissions</strong>. Facteurs déclenchants des poussées : <span class=\"kw-etio\">exposition solaire</span>, <span class=\"kw-etio\">œstrogènes</span>, <span class=\"kw-etio\">grossesse</span>, infections, stress physique ou psychique.</p>\n      <p><strong>Survie</strong> — taux de survie à <span class=\"kw-chiffre\">5 ans &gt; 90 %</span>, à <span class=\"kw-chiffre\">20 ans ≈ 80 %</span>.</p>\n      <p><strong>Facteurs de mauvais <span class=\"kw-def\">pronostic</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Terrain</span> — <span class=\"kw-clinique\">début pédiatrique</span>, sujets non caucasiens, <span class=\"kw-clinique\">sexe masculin</span>, bas niveau socio-économique.</li>\n        <li>Activité — <span class=\"kw-bio\">hypocomplémentémie de consommation</span>, présence de séquelles.</li>\n        <li><strong><span class=\"kw-alerte\">Atteintes viscérales</span></strong> — rénale, neurologique et hématologique, clairement associées à une <span class=\"kw-def\">mortalité</span> majorée.</li>\n      </ul>\n      <p><strong>Causes de <span class=\"kw-def\">mortalité</span></strong> :</p>\n      <ul>\n        <li><strong>Précoce</strong> — poussées lupiques incontrôlées, <span class=\"kw-alerte\">thromboses</span> (SAPL), infections (complications du traitement).</li>\n        <li><strong>À long terme</strong> — <span class=\"kw-alerte\">athérosclérose accélérée</span> (<span class=\"kw-def\">AVC</span>, <span class=\"kw-def\">IDM</span>), seule cause non améliorée ces dernières années ; cancers ; infections.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":3},{"id":"194-15","rang":"B","rubrique":"Prise en charge","titre":"Savoir que la pierre angulaire du traitement du LS est l’hydroxychloroquine, et connaître les principes du traitement des principales atteintes","contenu":"<p><strong>Objectif le plus tombé de l'item en QCM.</strong> L'<span class=\"kw-ttt\">hydroxychloroquine</span> (HCQ, antimalarique de synthèse) est la <strong>pierre angulaire</strong> du traitement : elle doit être prescrite à <strong>tous <span class=\"kw-clinique\">les</span> patients lupiques</strong>, sauf <span class=\"kw-ci\">contre-indication</span>.</p>\n      <p><strong>Traitement d'induction des poussées</strong> :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Traitement d'induction</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bénignes</strong> (cutanéo-articulaires)</td><td><span class=\"kw-ttt\">Hydroxychloroquine</span> → <span class=\"kw-ttt\">AINS</span> → <span class=\"kw-ttt\">corticoïdes</span> faible dose → <span class=\"kw-ttt\">méthotrexate</span> si insuffisant</td></tr>\n          <tr><td><strong>Séreuses</strong></td><td><strong>Péricardite légère :</strong> <span class=\"kw-ttt\">AINS</span> ± <span class=\"kw-ttt\">colchicine</span> ; <br><strong>Pleurésie / péricardite non sévère :</strong> <span class=\"kw-ttt\">corticoïdes</span> à doses intermédiaires ; <br><strong>Forme sévère :</strong> bolus IV de <span class=\"kw-ttt\">méthylprednisolone</span></td></tr>\n          <tr><td><strong>Sévères</strong> (rénale, neurologique, cardiaque)</td><td><span class=\"kw-ttt\">Corticoïdes fortes doses IV</span> puis relais PO + <strong><span class=\"kw-ttt\">immunosuppresseur</span> :</strong> <span class=\"kw-ttt\">cyclophosphamide</span> en 1re intention, <span class=\"kw-ttt\">mycophénolate mofétil</span> en alternative</td></tr>\n          <tr><td><strong>Hématologiques sévères</strong></td><td><span class=\"kw-ttt\">Corticoïdes forte dose IV</span> + <span class=\"kw-ttt\">immunoglobulines IV</span> pour <span class=\"kw-clinique\">les</span> thrombopénies sévères</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Traitement d'entretien</strong> — <span class=\"kw-ttt\">hydroxychloroquine</span> + <span class=\"kw-ttt\">immunosuppresseur</span> (<span class=\"kw-ttt\">azathioprine</span> ou <span class=\"kw-ttt\">mycophénolate mofétil</span>) ± <span class=\"kw-ttt\">corticothérapie</span> à faible dose, poursuivi plusieurs années.</p>\n      <p><strong>Mesures préventives associées</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Photoprotection</span> efficace — écran solaire d'indice <span class=\"kw-chiffre\">50+</span>, éviction solaire entre 12 et <span class=\"kw-chiffre\">16 h</span>.</li>\n        <li><span class=\"kw-ttt\">Sevrage</span> <span class=\"kw-clinique\">tabagique</span> et prise en charge des <span class=\"kw-etio\">FRCV</span> ; autosurveillance par <span class=\"kw-bio\">bandelette urinaire</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span>.</li>\n        <li>Planification des grossesses ; contraception — <span class=\"kw-ci\">œstroprogestatifs contre-indiqués</span> (microprogestatifs, macroprogestatifs et DIU possibles).</li>\n        <li>Vaccins anti-grippal, anti-pneumococcique et anti-COVID — <span class=\"kw-ci\">vaccins vivants contre-indiqués</span> en cas d'immunosuppression profonde.</li>\n        <li>Prise en charge en <span class=\"kw-def\">ALD 30</span> (exonération du ticket modérateur).</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> <span class=\"kw-ttt\">Hydroxychloroquine</span> = maculopathie <span class=\"kw-etio\">toxique</span> (œil de bœuf), <span class=\"kw-def\">surveillance</span> ophtalmologique annuelle après <span class=\"kw-chiffre\">5 ans</span> + <span class=\"kw-bio\">ECG</span> préalable. À TOUJOURS prescrire sauf <span class=\"kw-ci\">CI absolue</span> — c'est la pierre angulaire.</div>","frequence":11},{"id":"194-16","rang":"B","rubrique":"Prise en charge","titre":"Savoir que le traitement du SAPL thrombotique repose sur un traitement anticoagulant la plupart du temps à vie","contenu":"<p>Le traitement du <span class=\"kw-def\">SAPL thrombotique</span> repose sur une <strong><span class=\"kw-ttt\">anticoagulation</span> au long cours</strong>, le plus souvent <strong>à vie</strong>.</p>\n      <ul>\n        <li><strong>Phase aiguë</strong> — <span class=\"kw-ttt\">héparine</span> pour <span class=\"kw-clinique\">les</span> thromboses récentes.</li>\n        <li><strong>Relais au long cours</strong> — <span class=\"kw-ttt\">AVK</span> à vie, <span class=\"kw-bio\">INR</span> cible <span class=\"kw-chiffre\">2,5</span> (intervalle 2-3).</li>\n        <li><strong><span class=\"kw-ci\">AOD contre-indiqués</span></strong> — associés à un excès de risque <span class=\"kw-etio\">thrombotique</span> démontré dans le SAPL.</li>\n      </ul>\n      <p><strong>Modalités selon le contexte</strong> :</p>\n      <ul>\n        <li><strong>SAPL artériel</strong> — <span class=\"kw-def\">AVC</span> <span class=\"kw-etio\">ischémique</span> ou atteinte périphérique : <span class=\"kw-ttt\">AVK + aspirine</span> ; <span class=\"kw-def\">SCA</span> : <span class=\"kw-ttt\">AVK + bithérapie antiplaquettaire</span> à la phase aiguë.</li>\n        <li><strong>SAPL obstétrical</strong> — <span class=\"kw-ttt\">HBPM + aspirine</span><span class=\"kw-chiffre\"> 100-160 mg</span>/j pendant la <span class=\"kw-ci\">grossesse</span>, ± <span class=\"kw-ttt\">corticoïdes</span> selon le tableau clinico-<span class=\"kw-ttt\">biologique</span>.</li>\n        <li><strong><span class=\"kw-bio\">Anticorps anti-phospholipides</span> asymptomatiques</strong> — pas de consensus ; <span class=\"kw-ttt\">aspirine faible dose</span> (<span class=\"kw-chiffre\">160 mg</span>) préconisée.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> majeure.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">AOD</span> sont CI dans le SAPL — excès de risque <span class=\"kw-etio\">thrombotique</span> démontré. <span class=\"kw-ttt\">AVK</span> obl<span class=\"kw-chiffre\">iga</span>toires à vie (<span class=\"kw-bio\">INR</span> cible 2,5).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 340 — <span class=\"kw-def\">AVC</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Syndrome catastrophique des anti-phospholipides (<span class=\"kw-alerte\">CAPS</span>) <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale</span></strong></p><p><span class=\"kw-ttt\">Anticoagulation efficace</span> + <span class=\"kw-ttt\">corticothérapie fortes doses</span> + <span class=\"kw-ttt\">immunoglobulines IV</span> / <span class=\"kw-ttt\">plasmaphérèses</span> ; <span class=\"kw-ttt\">cyclophosphamide IV</span> si forme réfractaire</p><ul><li><span class=\"kw-def\">Thromboses microcirculatoires</span> multiples, diffuses et simultanées en <span class=\"kw-chiffre\">&lt; 1 semaine</span></li><li><span class=\"kw-alerte\">Défaillance multiviscérale</span> : <span class=\"kw-clinique\">atteinte rénale</span> (<span class=\"kw-chiffre\">90 %</span>), <span class=\"kw-clinique\">neurologique centrale</span>, <span class=\"kw-alerte\">SDRA</span></li><li><span class=\"kw-def\">Mortalité</span> <span class=\"kw-chiffre\">30–50 %</span> ; déclenché par une <span class=\"kw-etio\">infection</span> ou l'<span class=\"kw-etio\">arrêt de l'anticoagulation</span></li></ul><p><strong><span class=\"kw-clinique\">Poussée</span> lupique sévère <span class=\"q\">— atteinte viscérale menaçante</span></strong></p><p><span class=\"kw-ttt\">Corticoïdes fortes doses IV</span> (bolus de <span class=\"kw-ttt\">méthylprednisolone</span>) puis relais PO + <span class=\"kw-ttt\">immunosuppresseur</span> (<span class=\"kw-ttt\">cyclophosphamide</span>)</p><ul><li>Atteinte <span class=\"kw-alerte\">rénale</span>, <span class=\"kw-alerte\">neurologique</span> ou <span class=\"kw-alerte\">cardiaque</span> mettant en jeu le <span class=\"kw-alerte\">pronostic vital</span></li><li><span class=\"kw-clinique\">Thrombopénie sévère</span> : <span class=\"kw-ttt\">immunoglobulines IV</span> possibles</li></ul><p><strong>Thrombose aiguë du SAPL</strong></p><p><span class=\"kw-ttt\">Héparine</span> sans délai puis relais par <span class=\"kw-ttt\">AVK</span> ; <span class=\"kw-ci\">AOD contre-indiqués</span></p><ul><li><span class=\"kw-alerte\">AVC</span> ou <span class=\"kw-alerte\">IDM du sujet jeune</span> → doit faire évoquer un <span class=\"kw-def\">SAPL</span></li><li><span class=\"kw-clinique\">Thromboses spontanées</span> de sites inhabituels (veines abdominales, membre supérieur)</li></ul>","redflags":"<ul><li>Atteinte <span class=\"kw-alerte\">rénale</span>, <span class=\"kw-alerte\">neurologique</span> ou <span class=\"kw-alerte\">hématologique</span> → facteurs de <span class=\"kw-alerte\">mortalité majorée</span></li><li><span class=\"kw-alerte\">Défaillance multiviscérale</span> + <span class=\"kw-clinique\">thromboses diffuses</span> en <span class=\"kw-chiffre\">&lt; 1 semaine</span> → <span class=\"kw-def\">CAPS</span></li><li><span class=\"kw-bio\">CRP élevée</span> chez un lupique (habituellement basse) → évoquer <span class=\"kw-etio\">sérite</span>, <span class=\"kw-etio\">thrombose</span> ou <span class=\"kw-etio\">infection</span></li><li><span class=\"kw-bio\">Hypocomplémentémie de consommation</span> (<span class=\"kw-bio\">C3</span>, <span class=\"kw-bio\">C4</span>, <span class=\"kw-bio\">CH50</span> ↓) + <span class=\"kw-bio\">anti-ADN natif ↑</span> → <span class=\"kw-clinique\">poussée</span> évolutive</li><li><span class=\"kw-alerte\">AVC</span> ou <span class=\"kw-alerte\">IDM du sujet jeune</span>, thromboses récidivantes → <span class=\"kw-def\">SAPL</span></li><li><span class=\"kw-clinique\">Tamponnade</span> (péricardite) — rare mais possible</li></ul>","principes":"<p>Pas de traitement curatif. L'<span class=\"kw-ttt\">hydroxychloroquine</span> est la <strong>pierre angulaire</strong> du traitement de fond et doit être prescrite à <strong>tous</strong> <span class=\"kw-clinique\">les</span> patients lupiques, sauf <span class=\"kw-ci\">contre-indication</span>.</p><p><strong>Formes bénignes <span class=\"q\">— cutanéo-articulaires</span></strong></p><ul><li><span class=\"kw-ttt\">Hydroxychloroquine</span> (socle)</li><li><span class=\"kw-ttt\">AINS</span> pour <span class=\"kw-clinique\">les</span> atteintes articulaires mineures</li><li>Faibles doses de <span class=\"kw-ttt\">corticoïdes</span> si insuffisant (non recommandés en atteinte purement cutanée)</li><li><span class=\"kw-ttt\">Méthotrexate</span> sur l'atteinte cutanéo-articulaire, en association à l'<span class=\"kw-ttt\">hydroxychloroquine</span></li><li>Traitements locaux : <span class=\"kw-ttt\">dermocorticoïdes</span>, <span class=\"kw-ttt\">infiltrations</span></li></ul><p><strong>Atteintes séreuses</strong></p><ul><li>Péricardite pauci-symptomatique : <span class=\"kw-ttt\">AINS</span> ± <span class=\"kw-ttt\">colchicine</span></li><li>Pleurésie / péricardite non sévère : <span class=\"kw-ttt\">corticoïdes</span> à doses intermédiaires (très corticosensible)</li><li>Formes sévères : bolus IV de <span class=\"kw-ttt\">méthylprednisolone</span> ± <span class=\"kw-ttt\">immunosuppresseur</span> (épargne cortisonique)</li></ul><p><strong>Formes sévères <span class=\"q\">— <span class=\"kw-alerte\">risque vital</span> (rénale / neuro / cardiaque)</span></strong></p><ul><li><span class=\"kw-ttt\">Corticoïdes fortes doses IV</span> puis relais PO</li><li><span class=\"kw-ttt\">Cyclophosphamide</span> (principalement) ou <span class=\"kw-ttt\">mycophénolate mofétil</span> en induction</li><li>Thrombopénie sévère : <span class=\"kw-ttt\">immunoglobulines IV</span></li><li>Entretien plusieurs années : <span class=\"kw-ttt\">hydroxychloroquine</span> + <span class=\"kw-ttt\">azathioprine</span> ou <span class=\"kw-ttt\">MMF</span> ± <span class=\"kw-ttt\">corticothérapie</span> faible dose</li></ul><p><strong>SAPL</strong></p><ul><li>aPL asymptomatique : <span class=\"kw-ttt\">aspirine faible dose</span> (pas de consensus en <span class=\"kw-def\">prévention primaire</span>)</li><li>SAPL <span class=\"kw-etio\">thrombotique</span> : <span class=\"kw-ttt\">héparine</span> puis <span class=\"kw-ttt\">AVK à vie</span>, <span class=\"kw-bio\">INR</span> cible 2,5 (2–3)</li><li><span class=\"kw-ci\">AOD contre-indiqués</span> (excès de risque <span class=\"kw-etio\">thrombotique</span>)</li><li>SAPL obstétrical : <span class=\"kw-ttt\">HBPM</span> + <span class=\"kw-ttt\">aspirine</span> (<span class=\"kw-chiffre\">100–160 mg</span>/j) pendant la <span class=\"kw-ci\">grossesse</span></li></ul><p><strong>Mesures préventives & éviction</strong></p><ul><li><span class=\"kw-ttt\">Photoprotection</span> : éviction solaire <span class=\"kw-chiffre\">12–16 h</span>, écran indice 50+</li><li>Contrôle des <span class=\"kw-etio\">FRCV</span> : arrêt du <span class=\"kw-ttt\">tabac</span> +++</li><li><span class=\"kw-ci\">Contraception œstroprogestative contre-indiquée</span> → microprogestatif, DIU possibles</li><li><span class=\"kw-ttt\">Vaccins</span> <span class=\"kw-etio\">grippe</span> / <span class=\"kw-etio\">pneumocoque</span> / COVID ; <span class=\"kw-ci\">vaccins vivants CI</span> si immunosuppression profonde</li><li>Prévention de l'<span class=\"kw-alerte\">ostéoporose</span> sous <span class=\"kw-ttt\">corticothérapie</span> ; planifier <span class=\"kw-clinique\">les</span> grossesses</li></ul>","suivi":"<p><strong>Activité de la maladie</strong></p><ul><li><span class=\"kw-bio\">Anti-ADN natif</span> : taux corrélé à l'activité de la maladie</li><li><span class=\"kw-bio\">Complément</span> (<span class=\"kw-bio\">C3</span>, <span class=\"kw-bio\">C4</span>, ± <span class=\"kw-bio\">CH50</span>) : hypocomplémentémie de consommation = <span class=\"kw-clinique\">poussée</span></li></ul><p><strong><span class=\"kw-def\">Surveillance</span> <span class=\"kw-ttt\">biologique</span> standard</strong></p><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span></li><li>Autosurveillance par <span class=\"kw-bio\">bandelette urinaire</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span></li></ul><p><strong>Tolérance de l'<span class=\"kw-ttt\">hydroxychloroquine</span></strong></p><ul><li>Examen <span class=\"kw-clinique\">ophtalmologique</span> initial puis 1x/an après <span class=\"kw-chiffre\">5 ans</span> (risque de <span class=\"kw-alerte\">rétinopathie</span>)</li><li><span class=\"kw-bio\">ECG</span> préalable ; dosage de l'<span class=\"kw-bio\">hydroxychloroquine</span> pour vérifier l'observance</li></ul><p><strong><span class=\"kw-ci\">Grossesse</span> & SAPL</strong></p><ul><li><span class=\"kw-ci\">Grossesse</span> différée jusqu'à <span class=\"kw-chiffre\">≥ 1 an</span> après <span class=\"kw-clinique\">rémission</span> des formes sévères ; <span class=\"kw-def\">suivi</span> mensuel multidisciplinaire</li><li>Sous <span class=\"kw-ttt\">AVK</span> : <span class=\"kw-bio\">INR</span> cible 2,5</li></ul><p><strong>Prise en charge sociale</strong></p><ul><li><span class=\"kw-def\">ALD 30</span> : exonération du ticket modérateur</li></ul>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-17-6.php","label":"Collège (COFER) — Item cours 1 17 6"},{"href":"https://radiopaedia.org/articles/systemic-lupus-erythematosus","label":"Radiopaedia : Systemic lupus erythematosus"},{"href":"https://radiopaedia.org/articles/systemic-lupus-erythematosus-cns-manifestations","label":"Radiopaedia : Systemic lupus erythematosus cns manifestations"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"LES confirmé — type et gravité de l'atteinte ? — Hydroxychloroquine = pierre angulaire pour tous les patients (sauf CI)","detail":"<h4>CAT — stratégie thérapeutique du <span class=\"kw-clinique\">lupus</span> systémique — Tri sur le type et la gravité de l'atteinte (<span class=\"kw-ttt\">hydroxychloroquine</span> = socle pour tous)</h4>","branches":[{"to":"t-benigne","label":"Cutanéo-articulaire (forme bénigne)","color":"blue"},{"to":"t-sereuse","label":"Séreuse (pleurésie / péricardite)","color":"blue"},{"to":"q-severe","label":"Atteinte viscérale / hématologique sévère","color":"red"},{"to":"q-sapl","label":"Complication thrombotique (SAPL associé)","color":"red"}]},{"id":"t-benigne","kind":"terminal","label":"Forme bénigne cutanéo-articulaire","color":"blue","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hydroxychloroquine</span> (socle)</li><li><span class=\"kw-ttt\">AINS</span> pour <span class=\"kw-clinique\">les</span> atteintes articulaires mineures</li><li>Faibles doses de <span class=\"kw-ttt\">corticoïdes</span> si insuffisant (non recommandés en atteinte purement cutanée)</li><li><span class=\"kw-ttt\">Méthotrexate</span> sur l'atteinte cutanéo-articulaire, associé à l'<span class=\"kw-ttt\">hydroxychloroquine</span></li></ul><h4>Traitements locaux</h4><ul><li><span class=\"kw-ttt\">Dermocorticoïdes</span> (<span class=\"kw-clinique\">lupus</span> subaigu / chronique)</li><li><span class=\"kw-ttt\">Infiltrations</span> <span class=\"kw-ttt\">corticoïdes</span> (atteinte articulaire persistante)</li></ul>"},{"id":"t-sereuse","kind":"terminal","label":"Atteinte séreuse","color":"amber","detail":"<h4>Traitement</h4><ul><li>Péricardite pauci-symptomatique : <span class=\"kw-ttt\">AINS</span> ± <span class=\"kw-ttt\">colchicine</span></li><li>Pleurésie / péricardite non sévère : <span class=\"kw-ttt\">corticoïdes</span> à doses intermédiaires (très corticosensible)</li><li>Formes sévères : bolus IV de <span class=\"kw-ttt\">méthylprednisolone</span> ± <span class=\"kw-ttt\">immunosuppresseur</span> (épargne cortisonique)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Dépister une <span class=\"kw-alerte\">tamponnade</span> (rare mais possible)</li></ul>"},{"id":"q-severe","kind":"decision","label":"Quel organe est menacé ? — Atteinte mettant en jeu le pronostic vital","branches":[{"to":"t-viscerale","label":"Rénale / neurologique / cardiaque","color":"red"},{"to":"t-hemato","label":"Hématologique sévère","color":"red"}]},{"id":"t-viscerale","kind":"terminal","label":"Atteinte viscérale grave","color":"red","detail":"<h4>Induction</h4><ul><li><span class=\"kw-ttt\">Corticoïdes fortes doses IV</span> puis relais PO</li><li><span class=\"kw-ttt\">Cyclophosphamide</span> (principalement) ou <span class=\"kw-ttt\">mycophénolate mofétil</span> (alternative)</li></ul><h4>Entretien</h4><ul><li>Plusieurs années : <span class=\"kw-ttt\">hydroxychloroquine</span> + <span class=\"kw-ttt\">azathioprine</span> ou <span class=\"kw-ttt\">MMF</span> ± <span class=\"kw-ttt\">corticothérapie</span> faible dose</li></ul><h4>Atteinte rénale</h4><ul><li>Indication de <span class=\"kw-bio\">biopsie rénale</span> (PBR) pour classer la néphropathie</li></ul>"},{"id":"t-hemato","kind":"terminal","label":"Atteinte hématologique sévère","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticoïdes fortes doses IV</span> puis relais PO</li><li>Thrombopénie sévère : <span class=\"kw-ttt\">immunoglobulines IV</span></li></ul>"},{"id":"q-sapl","kind":"decision","label":"Présentation du SAPL ? — SAPL observé dans 20–30 % des LES","branches":[{"to":"t-sapl-thrombo","label":"Thrombose constituée (TVP, EP, AVC, IDM)","color":"red"},{"to":"t-sapl-obst","label":"Obstétrical / aPL asymptomatique","color":"amber"}]},{"id":"t-sapl-thrombo","kind":"terminal","label":"SAPL thrombotique","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Héparine</span> pour la thrombose récente, puis <span class=\"kw-ttt\">AVK à vie</span>, <span class=\"kw-bio\">INR</span> cible 2,5 (2–3)</li><li>SAPL artériel : <span class=\"kw-ttt\">AVK</span> + <span class=\"kw-ttt\">aspirine</span> ; <span class=\"kw-alerte\">SCA</span> : <span class=\"kw-ttt\">AVK</span> + bithérapie antiplaquettaire à la phase aiguë</li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">AOD contre-indiqués</span> dans le SAPL (excès de risque <span class=\"kw-etio\">thrombotique</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 226 (<span class=\"kw-def\">TVP</span> - EP) · Item 340 (<span class=\"kw-def\">AVC</span>) · Item 339 (<span class=\"kw-def\">SCA</span>)</li></ul>"},{"id":"t-sapl-obst","kind":"terminal","label":"SAPL obstétrical / aPL asymptomatique","color":"amber","detail":"<h4>SAPL obstétrical</h4><ul><li><span class=\"kw-ttt\">HBPM</span> + <span class=\"kw-ttt\">aspirine</span> (<span class=\"kw-chiffre\">100–160 mg</span>/j) dès le début de la <span class=\"kw-ci\">grossesse</span> ; ± <span class=\"kw-ttt\">corticoïdes</span> selon le tableau</li></ul><h4>aPL asymptomatique</h4><ul><li>Pas de consensus en <span class=\"kw-def\">prévention primaire</span> → <span class=\"kw-ttt\">aspirine faible dose</span> (<span class=\"kw-chiffre\">160 mg</span>) préconisée</li></ul><h4><span class=\"kw-ci\">Grossesse</span></h4><ul><li>Différer jusqu'à <span class=\"kw-chiffre\">≥ 1 an</span> après <span class=\"kw-clinique\">rémission</span> des formes sévères ; <span class=\"kw-def\">suivi</span> mensuel multidisciplinaire</li></ul>"}]},"cards":[{"i":"0c6cde76ec7d","n":194,"o":"194-1","u":"Définition","t":"Savoir que le lupus systémique (LS) est une maladie auto-immune polymorphe","q":"Pourquoi qualifie-t-on l'expression clinique du lupus systémique (LS) de « polymorphe » ?","a":"<p>L'expression clinique du lupus systémique est polymorphe car les <strong>premières manifestations peuvent intéresser n'importe quel organe</strong>, et les rechutes ne touchent pas forcément le même organe, rendant le diagnostic difficile du fait de ce <strong>caractère protéiforme</strong>.</p>"},{"i":"218d468d6eb9","n":194,"o":"194-1","u":"Définition","t":"Savoir que le lupus systémique (LS) est une maladie auto-immune polymorphe","q":"Quels sont les deux profils d'atteintes cliniques schématisés dans le lupus systémique (LS) ?","a":"<ul><li>Les <strong>formes bénignes et fréquentes</strong> avec des atteintes cutanéo-articulaires (comme le <strong>rash malaire</strong> ou les <strong>arthralgies</strong>), dont le pronostic est généralement favorable.</li><li>Les <strong>formes plus rares et sévères</strong>, impliquant des atteintes viscérales (rénale, neurologique, hématologique) qui peuvent mettre en jeu le pronostic vital.</li></ul>"},{"i":"276ff47cfab3","n":194,"o":"194-1","u":"Définition","t":"Savoir que le lupus systémique (LS) est une maladie auto-immune polymorphe","q":"Quelle est la définition du lupus systémique (LS) ?","a":"<p>Le lupus systémique (LS), également appelé lupus érythémateux systémique (LES), est une <strong>maladie auto-immune systémique</strong>, c'est-à-dire qu'elle n'est <strong>pas spécifique d'un organe</strong>.</p>"},{"i":"5cdcd99f2525","n":194,"o":"194-1","u":"Définition","t":"Savoir que le lupus systémique (LS) est une maladie auto-immune polymorphe","q":"Quels mécanismes immunologiques sont impliqués dans la physiopathologie du lupus systémique (LS) ?","a":"<p>La physiopathologie du lupus systémique implique une <strong>perte de tolérance aux antigènes du soi</strong>, mettant en jeu :</p><ul><li>La <strong>toxicité directe des auto-anticorps</strong> (auto-AC).</li><li>La formation de <strong>complexes immuns circulants</strong>.</li><li>Un <strong>défaut de clairance des corps apoptotiques</strong>.</li><li>L'activation de <strong>lymphocytes T et B autoréactifs</strong>.</li><li>L'activation des <strong>cellules dendritiques plasmacytoïdes</strong>, conduisant à une production d'<strong>interféron alpha</strong>.</li><li>L'<strong>activation du complément</strong>.</li></ul>"},{"i":"81c0553d4854","n":194,"o":"194-1","u":"Définition","t":"Savoir que le lupus systémique (LS) est une maladie auto-immune polymorphe","q":"Quelle est la particularité biologique du lupus systémique (LS) ?","a":"<p>Biologiquement, le lupus systémique est caractérisé par la présence d'<strong>auto-anticorps dirigés contre des antigènes d'origine nucléaire</strong>.</p>"},{"i":"09c84c47da98","n":194,"o":"194-10","u":"Examens complémentaires","t":"Connaître l’intérêt et l’interprétation du test de dépistage des anticorps anti-nucléaires (AAN)","q":"Comment interpréter un test de dépistage des anticorps anti-nucléaires (AAN) dans le contexte du lupus systémique ?","a":"<p>L'interprétation des anticorps anti-nucléaires (AAN) repose sur :</p><ul><li>Leur <strong>sensibilité quasi constante</strong> dans le lupus systémique : un titre <strong>&lt; 1/80</strong> rend le diagnostic très improbable et est un critère d'entrée majeur des classifications actuelles.</li><li>Leur <strong>faible spécificité (≈ 50 %)</strong> : des AAN positifs peuvent se retrouver dans d'autres maladies auto-immunes, des infections, des cancers, ou chez des sujets âgés sains.</li></ul>"},{"i":"41c1cb9c53ea","n":194,"o":"194-10","u":"Examens complémentaires","t":"Connaître l’intérêt et l’interprétation du test de dépistage des anticorps anti-nucléaires (AAN)","q":"Quel est l'intérêt du dépistage des anticorps anti-nucléaires (AAN) dans le diagnostic du lupus systémique ?","a":"<p>Les anticorps anti-nucléaires (AAN) constituent le <strong>test de dépistage de première intention</strong> du lupus systémique. Ils sont importants pour leur très haute <strong>sensibilité (≈ 100 %)</strong>, ce qui signifie qu'un lupus systémique est très improbable si les AAN sont négatifs.</p>"},{"i":"e0c5f06d6396","n":194,"o":"194-10","u":"Examens complémentaires","t":"Connaître l’intérêt et l’interprétation du test de dépistage des anticorps anti-nucléaires (AAN)","q":"Quelle est la technique de détection des anticorps anti-nucléaires (AAN) et quels éléments doivent être évalués pour leur interprétation ?","a":"<p>La détection des anticorps anti-nucléaires (AAN) se fait par <strong>immunofluorescence indirecte (IFI) sur cellules HEp-2</strong>. L'interprétation associe le <strong>titre</strong> (seuil de positivité <strong>&gt; 1/80</strong>) et l'<strong>aspect de la fluorescence</strong>, qui oriente vers des tests complémentaires spécifiques :</p><ul><li><strong>Homogène</strong> : oriente vers les anti-ADN natif, anti-Histone.</li><li><strong>Moucheté à gros grains</strong> : oriente vers les anti-Sm, anti-RNP.</li><li><strong>Moucheté fin</strong> : oriente vers les anti-SSA/Ro, anti-SSB/La.</li></ul>"},{"i":"613907eee2c8","n":194,"o":"194-2","u":"Définition","t":"Savoir que le syndrome des anti-phospholipides (SAPL) peut être primaire ou secondaire","q":"Quelle est la définition d'un SAPL primaire et sa prévalence approximative ?","a":"<p>Un SAPL primaire survient en l'absence de toute autre pathologie définie, de façon isolée. Il représente environ <strong>50 %</strong> des cas de SAPL.</p>"},{"i":"6ee1daacd9ed","n":194,"o":"194-2","u":"Définition","t":"Savoir que le syndrome des anti-phospholipides (SAPL) peut être primaire ou secondaire","q":"Quelle est la définition d'un SAPL secondaire, à quelle maladie est-il principalement associé et quelle est sa prévalence approximative ?","a":"<p>Un SAPL secondaire est associé à une autre maladie auto-immune, principalement le <strong>lupus systémique</strong>, où il est observé chez 20 à 30 % des patients lupiques. Il représente environ <strong>50 %</strong> des cas de SAPL.</p>"},{"i":"76b73b76daee","n":194,"o":"194-2","u":"Définition","t":"Savoir que le syndrome des anti-phospholipides (SAPL) peut être primaire ou secondaire","q":"Comment définit-on le syndrome des anti-phospholipides (SAPL) ?","a":"<p>Le syndrome des anti-phospholipides (SAPL) associe des manifestations <strong>thrombotiques</strong> ou <strong>obstétricales</strong> à la présence persistante d'<strong>anticorps anti-phospholipides</strong>.</p>"},{"i":"59aa43bf0dd8","n":194,"o":"194-5","u":"Diagnostic positif","t":"Connaître les principales lésions cutanées spécifiques","q":"Comment se manifestent les lésions cutanées spécifiques du lupus érythémateux subaigu ?","a":"<p>Les lésions cutanées spécifiques du lupus érythémateux subaigu se présentent sous forme de <strong>lésions annulaires polycycliques</strong> ou de <strong>lésions psoriasiformes</strong>.</p><ul><li>Elles sont associées à la présence d'anticorps <strong>anti-SSA/Ro</strong>.</li><li>En cas de grossesse, il existe un risque de <strong>lupus néonatal</strong>.</li></ul>"},{"i":"9a8780dcef62","n":194,"o":"194-5","u":"Diagnostic positif","t":"Connaître les principales lésions cutanées spécifiques","q":"Quelles sont les caractéristiques des lésions cutanées spécifiques du lupus érythémateux chronique (lupus discoïde) ?","a":"<p>Le lupus discoïde se manifeste par des <strong>plaques érythémato-squameuses</strong> qui présentent une <strong>atrophie centrale</strong> et des <strong>bouchons cornés folliculaires</strong>.</p><ul><li>Ces lésions sont <strong>cicatricielles</strong> et peuvent entraîner une <strong>alopécie définitive</strong> en zone pileuse.</li></ul>"},{"i":"d33bec1fefc5","n":194,"o":"194-5","u":"Diagnostic positif","t":"Connaître les principales lésions cutanées spécifiques","q":"Quelles sont les lésions cutanées spécifiques du lupus érythémateux aigu systémique (LES) ?","a":"<p>La principale lésion cutanée spécifique du LES aigu est le <strong>rash malaire</strong>, également appelé « véspertilio » en aile de papillon.</p><ul><li>Il est <strong>photosensible</strong>, touchant les zones photo-exposées.</li><li>Il <strong>ne laisse pas de cicatrice</strong> et n'est pas atrophiant.</li><li>Son évolution est souvent parallèle aux poussées de la maladie.</li></ul>"},{"i":"82784687e393","n":194,"o":"194-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de fréquence et de présentation clinique d’une atteinte rénale au cours du lupus systémique : œdèmes, bandelettes urinaires positives","q":"Quelle est la fréquence de l'atteinte rénale au cours du lupus systémique et son importance pronostique ?","a":"<p>L'atteinte rénale, ou <strong>néphropathie lupique</strong>, concerne environ <strong>40 %</strong> des patients atteints de lupus systémique. C'est un <strong>facteur pronostique majeur</strong>, son repérage précoce est déterminant pour le pronostic rénal et vital.</p>"},{"i":"906fd7501fcd","n":194,"o":"194-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de fréquence et de présentation clinique d’une atteinte rénale au cours du lupus systémique : œdèmes, bandelettes urinaires positives","q":"Quel est l'outil de dépistage clé de l'atteinte rénale dans le lupus systémique et quelle est la conduite à tenir en cas de positivité ?","a":"<p>La <strong>bandelette urinaire</strong> est l'outil de dépistage clé, réalisée <strong>tous les 6 mois</strong>. Elle recherche une <strong>protéinurie</strong> et une <strong>hématurie microscopique</strong>.</p><p>En cas de bandelette urinaire positive (protéinurie et/ou hématurie), il faut :</p><ul><li>Quantifier la protéinurie par un rapport Protéine/Créatinine (RPC) sur échantillon.</li><li>Doser la <strong>créatininémie</strong>.</li><li>Réaliser un <strong>ECBU</strong>.</li><li>Discuter une <strong>biopsie rénale</strong>.</li></ul>"},{"i":"d2a0f1c67396","n":194,"o":"194-6","u":"Diagnostic positif","t":"Connaître les caractéristiques de fréquence et de présentation clinique d’une atteinte rénale au cours du lupus systémique : œdèmes, bandelettes urinaires positives","q":"Comment se manifeste cliniquement une atteinte rénale au cours du lupus systémique ?","a":"<ul><li><strong>Œdèmes</strong> : traduisent un <strong>syndrome néphrotique</strong>, le plus souvent <strong>impur</strong> (associé à une HTA et/ou une hématurie).</li><li><strong>HTA</strong> : fréquente, surtout en cas de glomérulopathie grave. Elle est souvent asymptomatique au début.</li></ul>"},{"i":"1470acd1b0b2","n":194,"o":"194-8","u":"Contenu multimédia","t":"Photographie d’un vespertilio","q":"Quelle est la signification clinique du vespertilio dans le cadre du lupus systémique ?","a":"<p>Le vespertilio, ou rash malaire, est la <strong>lésion cutanée caractéristique du lupus aigu</strong>.</p>"},{"i":"889cddace0e5","n":194,"o":"194-8","u":"Contenu multimédia","t":"Photographie d’un vespertilio","q":"Comment décrire sémiologiquement un vespertilio chez un patient lupique ?","a":"<ul><li>Il s'agit d'un <strong>érythème en aile de papillon</strong>, bilatéral et symétrique.</li><li>Il touche les <strong>pommettes et le dos du nez</strong>.</li><li>Sa distribution est <strong>photo-exposée</strong>, mais il épargne typiquement les <strong>sillons nasogéniens</strong>.</li><li>Il est <strong>photosensible</strong>, c'est-à-dire déclenché ou aggravé par l'exposition solaire.</li></ul>"},{"i":"e17ea4be3925","n":194,"o":"194-8","u":"Contenu multimédia","t":"Photographie d’un vespertilio","q":"Quelle est l'évolution typique d'un vespertilio dans le lupus systémique, et comment le différencier d'autres lésions cutanées lupiques ?","a":"<p>Le vespertilio est une lésion <strong>non atrophiante</strong>. Il guérit <strong>sans cicatrice ni séquelle</strong>, ce qui le différencie notamment du lupus discoïde qui, lui, laisse des séquelles cicatricielles.</p>"}]};